$where=[];$types='';$params=[];if(!$all)$where[]='s.status=1';if($departmentId>0){$where[]='(s.departamento_id IS NULL OR s.departamento_id=?)';$types.='i';$params[]=$departmentId;}$sql="SELECT s.id,s.departamento_id,s.codigo,s.nombre,s.descripcion,s.status,d.nombre departamento_nombre FROM presupuesto_subitem s LEFT JOIN departamento d ON d.id=s.departamento_id".($where?' WHERE '.implode(' AND ',$where):'')." ORDER BY s.nombre";$st=$con->prepare($sql);if($types)$st->bind_param($types,...$params);$st->execute();$rs=$st->get_result();$data=[];while($r=$rs->fetch_assoc()){$r['id']=(int)$r['id'];$r['departamento_id']=$r['departamento_id']!==null?(int)$r['departamento_id']:null;$r['status']=(int)$r['status'];$data[]=$r;}$st->close();$con->close();json_response(['ok'=>true,'data'=>$data,'mode'=>'db']);
